// Convierte el historial del buffer en texto plano (sin llaves) para el modelo económico
const items = $input.all().map(i => i.json);
const msgs = (items.length === 1 && Array.isArray(items[0].messages)) ? items[0].messages : items;
const lineas = [];
for (const m of msgs) {
  if (m.human !== undefined || m.ai !== undefined) {           // formato agrupado { human, ai }
    if (m.human) lineas.push('CLIENTE: ' + m.human);
    if (m.ai) lineas.push('AGENTE: ' + m.ai);
    continue;
  }
  const tipo = String(m.type || m.role || (Array.isArray(m.id) ? m.id.slice(-1)[0] : '')).toLowerCase();
  const texto = m.content ?? m.text ?? m.kwargs?.content ?? m.data?.content ?? '';
  if (texto) lineas.push(((tipo.includes('human') || tipo === 'user') ? 'CLIENTE: ' : 'AGENTE: ') + texto);
}
return [{ json: { historial: lineas.join('\n').replace(/[{}]/g, ''), cantidad_mensajes: lineas.length } }];

