// Fuerza el contrato { asunto_principal: string, puntos_clave: array, accion_requerida: string }
const raw = String($input.first().json.text || '');
let o = null;
try { const m = raw.match(/\{[\s\S]*\}/); o = JSON.parse(m ? m[0] : raw); } catch (e) { o = null; }
const valido = !!o && typeof o.asunto_principal === 'string' && Array.isArray(o.puntos_clave) && typeof o.accion_requerida === 'string';
if (!valido) o = { asunto_principal: 'Resumen no disponible', puntos_clave: [], accion_requerida: 'Revisar manualmente la sesión' };
return [{ json: { resumen: { asunto_principal: o.asunto_principal, puntos_clave: o.puntos_clave.slice(0, 5).map(String), accion_requerida: o.accion_requerida }, resumen_valido: valido } }];

// Arma la fila a persistir: SOLO resumen y datos clave (nunca la conversación completa, logs ni HTML)
const ctx = $('Contexto de Memoria').first().json;
const integ = $('Integrar Resultado').isExecuted ? $('Integrar Resultado').first().json : $('Escape → Supervisor Humano').first().json;
let datos = {};
try { datos = JSON.parse(ctx.datos_clave || '{}'); } catch (e) { datos = {}; }
datos.ultima_categoria = integ.ruta;
if ($('Delegar a Worker 1 (Calificador)').isExecuted) {
  const w1 = $('Delegar a Worker 1 (Calificador)').first().json;
  const lead = w1?.data?.lead;
  const ok = v => v !== undefined && v !== null && v !== '' && v !== 'No informado';
  if (lead && typeof lead === 'object') {
    if (ok(lead.Nombre)) datos.nombre = lead.Nombre;
    if (ok(lead.Empresa)) datos.empresa = lead.Empresa;
    if (ok(lead.Email)) datos.email = lead.Email;
    if (ok(lead.Clasificacion)) datos.clasificacion_lead = lead.Clasificacion;
    if (ok(lead.Puntaje_BANT)) datos.puntaje_bant = lead.Puntaje_BANT;
  }
}
const estadoBase = integ.ruta === 'ESCALAMIENTO_HUMANO' ? 'DERIVADO A SUPERVISOR HUMANO'
  : (integ.status === 'success' ? integ.ruta + ' · ATENDIDO POR AGENTE' : integ.ruta + ' · ERROR - REVISAR');
let resumen, estado;
if ($('Validar JSON del Resumen').isExecuted) {
  const r = $('Validar JSON del Resumen').first().json.resumen;
  resumen = JSON.stringify(r);
  estado = estadoBase + ' · Acción: ' + r.accion_requerida;
} else {
  resumen = ctx.resumen_previo_raw && ctx.resumen_previo_raw !== 'Sin historial previo.' ? ctx.resumen_previo_raw
    : 'Sin resumen consolidado todavía (la sesión no supera 5 mensajes).';
  estado = estadoBase;
}
return [{ json: {
  'Session_ID': ctx.session_id,
  'Fecha de actualización': $now.setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd HH:mm'),
  'Resumen consolidado': resumen,
  'Estado del caso': estado,
  'Datos clave': JSON.stringify(datos),
  'Cantidad de mensajes': ctx.mensajes_actual
} }];
